const queries = [
  { q: 'subject:(arabic dubbed) mediatype:movies', origin: 'american', lang: 'ar_dubbed' },
  { q: 'collection:feature_films subject:(arabic) mediatype:movies', origin: 'american', lang: 'ar_dubbed' },
  { q: 'subject:(مدبلج) mediatype:movies', origin: 'other', lang: 'ar_dubbed' },
  { q: 'subject:(فيلم عربي) mediatype:movies', origin: 'moroccan', lang: 'ar' },
  { q: 'subject:(bollywood arabic) mediatype:movies', origin: 'indian', lang: 'ar_dubbed' },
  { q: 'collection:opensource_movies subject:(arabic) mediatype:movies', origin: 'other', lang: 'ar' }
];
return queries.map(q => ({ json: q }));

const body = $input.first().json;
const query = $('Archive Queries').item.json;
const docs = body?.response?.docs || [];

const MIN_DUR = 2100; // 35 min

function parseRuntime(r) {
  if (!r) return null;
  if (typeof r === 'number') return r;
  const s = String(r);
  const parts = s.split(':').map(Number);
  if (parts.length === 3) return parts[0]*3600 + parts[1]*60 + parts[2];
  if (parts.length === 2) return parts[0]*60 + parts[1];
  return parseInt(s) || null;
}

const candidates = docs
  .filter(d => d.identifier && d.title)
  .map(d => {
    const dur = parseRuntime(d.runtime);
    return {
      platform: 'archive',
      platform_id: d.identifier,
      title_raw: d.title,
      type: 'film',
      origin: query.origin || 'other',
      language: query.lang || 'ar_dubbed',
      category: 'drama',
      year: d.year ? parseInt(d.year) : null,
      duration_sec: dur,
      poster_url: `https://archive.org/services/img/${d.identifier}`,
      embed_url: `https://archive.org/embed/${d.identifier}`,
      embeddable: true,
      source_url: `https://archive.org/details/${d.identifier}`,
      keyword: query.q,
      source_workflow: '05-archive-org-discover'
    };
  })
  .filter(d => {
    // Only accept items with a valid duration (proxy for real video file)
    if (!d.duration_sec) return false;
    return d.duration_sec >= MIN_DUR;
  });

console.log(`[Archive] '${query.q}' → ${candidates.length} candidates`);
return [{ json: { candidates, query: query.q } }];
